-- "Armário de Personagem" — build a shareable character sheet (equipment +
-- souls + level/exp) with a public read-only link, mainly to make selling a
-- character on the Marketplace easier (no more typing out a giant item list).

-- ============================================================================
-- Item catalog, imported once from pristontale.eu's own database endpoint
-- (https://pristontale.eu/database/catalog?entity=items) — no public API is
-- documented, so this is a point-in-time import; re-run the same fetch +
-- transform later to refresh it. Admin-write / public-read, like other
-- reference-data tables in this project.
-- ============================================================================
create table if not exists public.wardrobe_items (
  id         bigint primary key,       -- pristontale.eu's own item id
  slot       text not null check (slot in ('amulet','ring','bracelet','sheltom','gauntlet','boot','armor','weapon_1h','weapon_2h','orb','shield')),
  name       text not null,
  subtype    text not null default '', -- e.g. 'Swords', 'Axes', 'Robe'...
  rarity     text not null check (rarity in ('common','uncommon','rare','epic','legendary')),
  level      int not null default 0,
  icon_url   text not null,
  created_at timestamptz not null default now()
);
create index if not exists wardrobe_items_slot_idx on public.wardrobe_items(slot);
alter table public.wardrobe_items enable row level security;
drop policy if exists wardrobe_items_read on public.wardrobe_items;
create policy wardrobe_items_read on public.wardrobe_items for select using (true);
drop policy if exists wardrobe_items_admin on public.wardrobe_items;
create policy wardrobe_items_admin on public.wardrobe_items for all
  using (public.is_admin()) with check (public.is_admin());

-- ============================================================================
-- Character sheets. `slug` is the unguessable public id (never a login/edit
-- key) — anyone with the link can view; only the owner (or admin) can edit.
--
-- `equipment` is a jsonb map { slotKey: { itemId, rarity, aging } | null } for
-- the 11 equip slots (amulet, ring1, ring2, sheltom, bracelet, gauntlet, boot,
-- armor, weapon1h, weapon2h, offhand). `rarity` is chosen per equip, NOT taken
-- from wardrobe_items.rarity — in-game the same item can be refined to any of
-- the 5 tiers, so the catalog's rarity is only a starting suggestion.
-- `souls` is a jsonb array of { id, level } — `id` from the exact same Souls
-- catalog as the Soul Tree (src/data/souls.json), `level` 1-3 like in-game.
-- ============================================================================
create table if not exists public.wardrobe_characters (
  id                     uuid primary key default gen_random_uuid(),
  owner_id               uuid not null references public.profiles(id) on delete cascade,
  slug                   text not null unique,
  nick                   text not null,
  class                  text not null check (class in ('fighter','archer','mechanician','assassin','pikeman','knight','shaman','priestess','magician','atalanta')),
  level                  int not null default 1 check (level >= 1),
  exp_pct                numeric not null default 0 check (exp_pct >= 0 and exp_pct <= 100),
  notes                  text not null default '',
  price_coins            bigint,
  price_gold             bigint,
  contact_whatsapp       text not null default '',
  contact_discord        text not null default '',
  listed_on_marketplace  boolean not null default false,
  equipment              jsonb not null default '{}',
  souls                  jsonb not null default '[]',
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now()
);
create index if not exists wardrobe_characters_owner_idx on public.wardrobe_characters(owner_id);
alter table public.wardrobe_characters enable row level security;
drop policy if exists wardrobe_characters_read on public.wardrobe_characters;
create policy wardrobe_characters_read on public.wardrobe_characters for select using (true);
drop policy if exists wardrobe_characters_insert on public.wardrobe_characters;
create policy wardrobe_characters_insert on public.wardrobe_characters for insert with check (owner_id = auth.uid());
drop policy if exists wardrobe_characters_update on public.wardrobe_characters;
create policy wardrobe_characters_update on public.wardrobe_characters for update
  using (owner_id = auth.uid() or public.is_admin()) with check (owner_id = auth.uid() or public.is_admin());
drop policy if exists wardrobe_characters_delete on public.wardrobe_characters;
create policy wardrobe_characters_delete on public.wardrobe_characters for delete
  using (owner_id = auth.uid() or public.is_admin());

-- ============================================================================
-- Seed: 749 equipable items (armor/robe, boots, gauntlets, bracelets, rings,
-- amulets, sheltoms, one/two-handed weapons, shields, orbs) imported from
-- pristontale.eu. Costumes, potions, souls, premium/lootbox items etc. are
-- deliberately excluded — souls come from the Soul Tree's own data instead.
-- ============================================================================
on conflict (id) do update set slot = excluded.slot, name = excluded.name, subtype = excluded.subtype, rarity = excluded.rarity, level = excluded.level, icon_url = excluded.icon_url;

on conflict (id) do update set slot = excluded.slot, name = excluded.name, subtype = excluded.subtype, rarity = excluded.rarity, level = excluded.level, icon_url = excluded.icon_url;

on conflict (id) do update set slot = excluded.slot, name = excluded.name, subtype = excluded.subtype, rarity = excluded.rarity, level = excluded.level, icon_url = excluded.icon_url;

on conflict (id) do update set slot = excluded.slot, name = excluded.name, subtype = excluded.subtype, rarity = excluded.rarity, level = excluded.level, icon_url = excluded.icon_url;

